package main

import (
	"gno.land/r/gov/dao"
	valv3 "gno.land/r/sys/validators/v3"
)

func main(cur realm) {
	r := valv3.NewValidatorProposalRequest(
		cross(cur),
		[]valv3.ValoperChange{
			valv3.NewValoperChange(address("g1yvkqqrzkdlp07nup2strr3n4p2m9upn9ec7wpz"), 5),
			valv3.NewValoperChange(address("g1sxvcr9xp0tqcqjheaeqmzjw3tqt6nm2gsv0n9e"), 5),
			valv3.NewValoperChange(address("g1pjlefcnqulegeycg53xuk87qu49qg5rdnw9g6f"), 5),
		},
		"Add 3 validator(s) to the valset",
		"Batch-add 3 operator(s) to the active valset with voting power 5.",
	)
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposalSimple(cross(cur), int64(pid), "YES")
	dao.ExecuteProposal(cross(cur), pid)
}
